export function normalizeShopSearch(value) {
  return String(value || "")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function levenshteinDistance(left, right) {
  let previous = Array.from({ length: right.length + 1 }, (_, index) => index);
  for (let i = 1; i <= left.length; i += 1) {
    const current = [i];
    for (let j = 1; j <= right.length; j += 1) {
      current[j] = Math.min(
        previous[j] + 1,
        current[j - 1] + 1,
        previous[j - 1] + (left[i - 1] === right[j - 1] ? 0 : 1)
      );
    }
    previous = current;
  }
  return previous[right.length];
}

/** Scores substring, prefix, and small spelling-error matches without a dependency. */
export function shopSearchScore(query, candidate) {
  const needle = normalizeShopSearch(query);
  const haystack = normalizeShopSearch(candidate);
  if (!needle || !haystack) return 0;
  if (haystack.includes(needle)) return 1000 - haystack.indexOf(needle);
  if (needle.length < 4) return 0;

  const distance = levenshteinDistance(needle, haystack);
  const allowed = Math.max(1, Math.floor(Math.max(needle.length, haystack.length) * 0.24));
  return distance <= allowed ? 500 - distance * 10 : 0;
}

export function shopRowSearchScore(query, row) {
  const itemScore = Math.max(
    shopSearchScore(query, row?.itemName),
    shopSearchScore(query, row?.itemTag),
    shopSearchScore(query, row?.displayItemName)
  );
  return Math.max(itemScore + (itemScore ? 50 : 0), shopSearchScore(query, row?.seller));
}

export function rankShopSuggestions(rows, query, limit = 7) {
  if (!normalizeShopSearch(query)) return [];
  const suggestions = new Map();
  for (const row of rows) {
    const name = row?.itemName || row?.itemTag || row?.displayItemName;
    const score = shopSearchScore(query, name);
    if (!name || !score) continue;
    const key = normalizeShopSearch(name);
    const previous = suggestions.get(key);
    if (!previous || score > previous.score) suggestions.set(key, { name, score });
  }
  return [...suggestions.values()]
    .sort((a, b) => b.score - a.score || a.name.localeCompare(b.name))
    .slice(0, limit)
    .map((suggestion) => suggestion.name);
}
